"""R34 A6: reconcile SI evidence; preserve all three as deferred, no guessed graph."""
import json,re
from pathlib import Path
from scripts.operate import ROOT,write,event
from scripts.task016_p7_r18_PMC_originals import now,sha,load,lines,put
from scripts.task016_p7_orchestrate import freeze_stage_manifest,verify_stage_chain
T="TASK-016-P7";B=Path("outputs/task016-p7/v1")
R=B/"SS/E02/fresh/SS-E02-R34-three-ACS-SI-science-v1"
G5=B/"SS/E02/stages/batches/SS-E02-R34-three-ACS-SI-science/G5_FRESH_HOLDOUT_ACQUIRE.json"
G6=G5.parent/"G6_IDENTITY_STRUCTURE_ADMIT.json"
FACTS={
 "10.1021/acs.jafc.5c06227":dict(pages=[2,5,6],observed="SI Figure S4 p5 shows SlUGT75C1 assays labelled K+UDP-Glc and Q+UDP-Glc with monosaccharide mass increments. Figure S1 is tomato metabolite LC-MS/MS. No acceptor-inner-sugar O2 single-step reaction is established by these SI panels.",disposition="deferred_SI_does_not_establish_frozen_SS_O2_reaction",needs=["main article enzyme-assay assignment and product site","original full product/acceptor stereochemical graph","independent graphic transcription if structure figures obtained"],needles=[(5,"products generated by SlUGT75C1"),(6,"Michaelis-Menten")]),
 "10.1021/acs.jafc.4c03824":dict(pages=[4,5,10,11,12,13,14,16,17,18],observed="SI Figure S2 pp4-5 explicitly starts from quercetin and identifies Q7G/Q3G/Q4-prime-G; Figure S4 pp10-11 refers product P1-P13 assignments to unavailable main Figure5. Figure S5 pp12-14 measures tissue rutin and kaempferol rutinoside after suppression; metabolite tables include triglycosides and a 2-doubleprime rhamnoside, which are not direct frozen UDP-Glc inner-sugar-O2 assays.",disposition="deferred_main_product_assignment_and_direct_SS_O2_assay_missing",needs=["main Figures4B/5 product assignments and original assay contexts","actual acceptor, donor and sugar-O2 bond with stereo","resolve SI K7/K3G label conflict without rewriting source"],needles=[(4,"quercetin as the substrate"),(5,"Q7G, Q3G"),(11,"Figure 5 of the main text")],source_annotation_conflict="p10 says kaempferol 7-O-glucoside (K3G); p11 says K7G. Retain both, do not silently correct."),
 "10.1021/acs.jafc.4c00488":dict(pages=[7,8,9],observed="SI Figure S6/S7 pp7-8 identify K=kaempferol, M=myricetin, G=gossypetin, Q=quercetagetin with UDP-Gal/UDP-Glu for LbUGT78AE1/72CT1/71BX1/71BX2. These displayed pH/kinetic assays use aglycones; transient-expression LC-MS is not a complete direct sugar-sugar O2 reaction. Other official tabular SI record remains separately discoverable and unprocessed.",disposition="deferred_displayed_aglycone_assays_and_main_assignment_missing",needs=["main original site/product assignment","other official tabular SI if relevant","source-qualified full SS reaction graph"],needles=[(7,"K, kaempferol"),(8,"UDP-Gal")])
}
def normalize(s):return re.sub(r"\s+","",s).casefold()
def main():
 if (ROOT/G6).exists():raise RuntimeError("IMMUTABLE")
 verify_stage_chain(ROOT/G5,sha(G5))
 contract=load(R/"pre_science_exposure_contract.json")
 a3=load(R/"A3/original_SI_front_identity.json")
 readers={role:load(R/role/"independent_original_text_extraction.json") for role in ("A4","A5")}
 receipts=lines(R/"scientific_exposure_reads.jsonl")
 assert len(receipts)==9 and all(sum(x["agent_role"]==r for x in receipts)==3 for r in ("A3","A4","A5"))
 out=[];checks=[]
 for source in contract["source_universe"]:
  doi=source["DOI"];fact=FACTS[doi];per={}
  for role,manifest in readers.items():
   rec=next(x for x in manifest["records"] if x["source_id"]==doi)
   assert rec["original_SHA"]==source["original_SHA"] and rec["peer_final_read"] is False
   p=Path(rec["pages_path"]);assert sha(p)==rec["pages_SHA"]
   per[role]=load(p)["pages"]
  assert len(per["A4"])==len(per["A5"])==next(x["page_count"] for x in a3["records"] if x["source_id"]==doi)
  for page,needle in fact["needles"]:
   ok=all(normalize(needle) in normalize(next(x["text"] for x in per[role] if x["page"]==page)) for role in ("A4","A5"))
   checks.append(dict(source_id=doi,page=page,needle=needle,both_independent_parsers_match=ok))
   assert ok,(doi,page,needle)
  evidence=[dict(page=p,original_SHA=source["original_SHA"],A4_text_SHA=next(x["text_SHA"] for x in per["A4"] if x["page"]==p),A5_text_SHA=next(x["text_SHA"] for x in per["A5"] if x["page"]==p)) for p in fact["pages"]]
  out.append(dict(source_id=doi,original_SHA=source["original_SHA"],original_SI_identity_verified=True,source_science_scope="exact available official SI only; main article unavailable",evidence=evidence,source_observation=fact["observed"],final_disposition=fact["disposition"],pending_evidence=fact["needs"],source_annotation_conflict=fact.get("source_annotation_conflict"),independent_text_extractors=2,independent_full_graph_transcriptions=0,frozen_SS_O2_source_reaction_established=False,whole_paper_SS_O2_absence_claim=False,chemical_qualification="deferred",product_graph=None,acceptor_graph=None,donor_graph=None,stereo=None,reference_precursors=None,full_alias_graph_closure=False,scope_applicability=None,structure_complete=False,runtime_executable=False,fresh_admitted=False,new_qualified_closure_group=False))
 inputs=[G5,R/"pre_science_exposure_contract.json",R/"A3/original_SI_front_identity.json",R/"scientific_exposure_reads.jsonl",R/"A6/visual_page_manifest.json",Path("scripts/task016_p7_ss_r34_A6.py")]
 for role in ("A4","A5"):
  inputs.append(R/role/"independent_original_text_extraction.json")
  inputs.extend(Path(rec["pages_path"]) for rec in readers[role]["records"])
 put(R/"A6/scientific_SI_dispositions.json",dict(task=T,agent_role="A6",epoch_id="SS-E02",at=now(),approval_type="agent_delegated",human_reviewed=False,input_manifest_sha={str(p):sha(p) for p in inputs},records=out,caption_crosschecks=checks,independent_extraction_note="Two isolated text parsers, not two completed molecular-graph or chemical reviews",A6_visual_pages_actually_viewed=[dict(source_id="10.1021/acs.jafc.5c06227",pages=[2,5]),dict(source_id="10.1021/acs.jafc.4c03824",pages=[12,14]),dict(source_id="10.1021/acs.jafc.4c00488",pages=[7])],counts=dict(processed=3,passed=0,rejected=0,pending=3),errors=[],unprocessed=[],read_holdout=True,read_model_outcome=False,qualified_new_closure_groups=0,complete_graphs=0,fresh_admitted=0,source_saturation=False,complete_full_qualification_round=False,pending_prior_old_R12_drift=True))
 inputs.append(R/"A6/scientific_SI_dispositions.json")
 freeze_stage_manifest(ROOT/G6.parent,"G6_IDENTITY_STRUCTURE_ADMIT",inputs,G5,expected_previous_sha=sha(G5),family="SS",epoch_id="SS-E02")
 verify_stage_chain(ROOT/G6,sha(G6))
 ledger=B/"epoch_ledger.jsonl"
 r=dict(task=T,family="SS",epoch_id="SS-E02",stage="G6_IDENTITY_STRUCTURE_ADMIT",status="active",at=now(),event_type="R34_three_official_SI_science_deferred_no_full_SS_graph",stage_manifest_path=str(G6),stage_manifest_sha256=sha(G6),source_count=3,original_SI_identity_verified=3,structure_complete=0,fresh_admitted=0,source_scope_positive=0,approval_type="agent_delegated",human_reviewed=False,read_model_outcome=False)
 write(T,str(ledger),(ROOT/ledger).read_text()+json.dumps(r,ensure_ascii=False,sort_keys=True)+"\n")
 print(json.dumps(dict(G6=sha(G6),original_SIs=3,caption_checks=len(checks),scientifically_deferred=3,structure_complete=0,fresh=0)))
if __name__=="__main__":main()
